package com.playsphere.report;import com.playsphere.common.Ids;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="reports") public class Report{@Id @Column(length=36)private String id;@Column(name="reporter_user_id",nullable=false,length=36)private String reporterUserId;@Column(name="target_type",nullable=false,length=32)private String targetType;@Column(name="target_id",nullable=false,length=36)private String targetId;@Column(nullable=false,length=120)private String reason;@Column(nullable=false,length=1000)private String description;@Column(nullable=false,length=24)private String status;@Column(nullable=false,length=16)private String priority;@Column(name="assigned_admin_user_id",length=36)private String assignedAdminUserId;@Column(name="resolution_note",length=1000)private String resolutionNote;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="resolved_at")private Instant resolvedAt;protected Report(){}public Report(String u,ReportController.CreateReport r){id=Ids.uuid();reporterUserId=u;targetType=r.targetType();targetId=r.targetId();reason=r.reason();description=r.description();priority=r.priority();status="OPEN";createdAt=Instant.now();}public String getId(){return id;}public String getReporterUserId(){return reporterUserId;}public String getTargetType(){return targetType;}public String getTargetId(){return targetId;}public String getReason(){return reason;}public String getDescription(){return description;}public String getStatus(){return status;}public String getPriority(){return priority;}public String getAssignedAdminUserId(){return assignedAdminUserId;}public String getResolutionNote(){return resolutionNote;}public Instant getCreatedAt(){return createdAt;}public Instant getResolvedAt(){return resolvedAt;}public void resolve(String admin,String status,String note){assignedAdminUserId=admin;this.status=status;resolutionNote=note;resolvedAt=Instant.now();}}
